let resultsOut = [];
for (const item of $input.all()) {
  const tavilyResponse = item.json;
  // Fallback to topic from previous node if available
  let topic = "Unknown";
  try { topic = $('Set Topic Input').first().json.topic; } catch(e) {}

  const results = tavilyResponse.results || [];
  const answer = tavilyResponse.answer || (results.length > 0 ? results[0].content : "No summary available.");

  const sources = results.map(r => ({
    url: r.url,
    title: r.title,
    snippet: r.content
  }));

  // derive 2-4 short facts from result snippets
  const key_facts = results.slice(0, 3).map(r => r.content.substring(0, 100) + '...');

  const research = {
    status: "completed",
    sources: sources,
    summary: answer,
    key_facts: key_facts,
    completed_at: new Date().toISOString()
  };

  resultsOut.push({
    json: {
      topic: topic,
      research: research
    }
  });
}
return resultsOut;

